// Repair any transaction a previous run left interrupted, before
// touching anything else.
let recovered = recover(&db_path)?;

/// Clone `source` to `destination` via `clonefile(2)`: an APFS
/// copy-on-write clone sharing data blocks until either file is written.
///
/// `destination` must not exist (`clonefile` fails with EEXIST — the
/// transaction engine relies on this: it never clones onto a live target,
/// only onto a fresh temp path). Symlinks are not followed.
#[cfg(target_os = "macos")]
pub fn clone_file(source: &Path, destination: &Path) -> io::Result<()> {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt;

    // From <sys/clonefile.h>; not bound by the libc crate.
    const CLONE_NOFOLLOW: u32 = 0x0001;

    let src = CString::new(source.as_os_str().as_bytes())
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "source path contains NUL"))?;
    let dst = CString::new(destination.as_os_str().as_bytes())
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "destination path contains NUL"))?;

    let result = unsafe { libc::clonefile(src.as_ptr(), dst.as_ptr(), CLONE_NOFOLLOW) };
    if result == 0 {
        Ok(())
    } else {
        Err(io::Error::last_os_error())
    }
}

#[cfg(not(target_os = "macos"))]
pub fn clone_file(_source: &Path, _destination: &Path) -> io::Result<()> {
    Err(io::Error::new(
        io::ErrorKind::Unsupported,
        "APFS cloning requires macOS",
    ))
}

#[test]
fn clone_shares_content_but_diverges_on_write() {
    let dir = tempfile::tempdir().unwrap();
    let source = dir.path().join("source.bin");
    let cloned = dir.path().join("cloned.bin");
    let data = vec![0x5au8; 256 * 1024];
    fs::write(&source, &data).unwrap();

    clone::clone_file(&source, &cloned).unwrap();

    // Same content, different inode: a real clone, not a hardlink.
    assert_eq!(fs::read(&cloned).unwrap(), data);
    let src_meta = fs::metadata(&source).unwrap();
    let clone_meta = fs::metadata(&cloned).unwrap();
    assert_ne!(src_meta.ino(), clone_meta.ino());
    assert_eq!(clone_meta.len(), data.len() as u64);

    // Copy-on-write isolation: writing the clone leaves the source alone.
    fs::write(&cloned, b"diverged").unwrap();
    assert_eq!(fs::read(&source).unwrap(), data);
}

#[test]
fn clone_refuses_existing_destination() {
    let dir = tempfile::tempdir().unwrap();
    let source = dir.path().join("source.bin");
    let dest = dir.path().join("existing.bin");
    fs::write(&source, b"source").unwrap();
    fs::write(&dest, b"already here").unwrap();

    let err = clone::clone_file(&source, &dest).unwrap_err();
    assert_eq!(err.raw_os_error(), Some(libc::EEXIST));
    assert_eq!(fs::read(&dest).unwrap(), b"already here");
}

/// True when the filesystem holding `path` is APFS. Cloning is an
/// APFS-only feature; HFS+, network mounts, etc. must be rejected.
#[cfg(target_os = "macos")]
pub fn is_apfs(path: &Path) -> io::Result<bool> {
    use std::ffi::{CStr, CString};
    use std::os::unix::ffi::OsStrExt;

    let c_path = CString::new(path.as_os_str().as_bytes())
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "path contains NUL"))?;
    let mut sfs: libc::statfs = unsafe { std::mem::zeroed() };
    let rc = unsafe { libc::statfs(c_path.as_ptr(), &mut sfs) };
    if rc != 0 {
        return Err(io::Error::last_os_error());
    }
    let fstype = unsafe { CStr::from_ptr(sfs.f_fstypename.as_ptr()) };
    Ok(fstype.to_bytes() == b"apfs")
}

/// Identifies a mounted volume (`st_dev`). APFS cloning only works when
/// source and target share a `VolumeId`, and the check must be repeated at
/// preflight time because volumes can unmount and remount between runs.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct VolumeId(pub u64);

/// Stored content identity: SHA-256 of the data fork. Hashes nominate
/// duplicate candidates; a byte-for-byte comparison is the final authority
/// before any replacement.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct ContentId(pub [u8; 32]);

/// One eligible regular file recorded during enumeration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FileEntry {
    pub path: PathBuf,
    pub dev: u64,
    pub ino: u64,
    pub nlink: u64,
    pub size: u64,
    pub mtime_sec: i64,
    pub mtime_nsec: i64,
    /// Resource-fork length (`com.apple.ResourceFork` xattr), 0 if absent.
    /// Part of the grouping key: files whose forks differ are not
    /// macOS-identical even when their data forks match.
    pub rsrc_len: u64,
}

/// Targets that can actually be reclaimed: a different inode than the
/// source (hardlinks of the source already share storage) and no other
/// hardlinks (replacing one path of a multi-link inode would silently
/// break the link relationship for paths outside our view).
pub fn eligible_targets(&self) -> impl Iterator<Item = &GroupMember> {
    let source_ino = self.source().ino;
    self.members
        .iter()
        .filter(move |m| m.ino != source_ino && m.nlink == 1)
}

/// Bytes stored beyond one copy: size × (distinct inodes − 1).
pub fn logical_duplicate_bytes(&self) -> u64 {
    self.size * (self.distinct_inodes() - 1)
}

/// Estimate only: APFS free-space accounting, snapshots, and prior
/// clones can make the observed change differ.
pub fn estimated_reclaimable_bytes(&self) -> u64 {
    self.size * self.eligible_targets().count() as u64
}

/// Default source selection: oldest modification time wins, ties broken by
/// lexicographically smallest path. Deterministic so repeated runs pick the
/// same source. The source is only ever read, never written, during a
/// reclamation transaction.
pub fn choose_source(members: &[FileEntry]) -> usize {
    assert!(!members.is_empty(), "cannot choose a source from no members");
    let mut best = 0;
    for (i, candidate) in members.iter().enumerate().skip(1) {
        let b = &members[best];
        let candidate_key = (candidate.mtime_sec, candidate.mtime_nsec, &candidate.path);
        let best_key = (b.mtime_sec, b.mtime_nsec, &b.path);
        if candidate_key < best_key {
            best = i;
        }
    }
    best
}

