/// Per-target outcome of a dry run: the plan plus its preflight verdict.
pub type DryRunResult = (TxnPlan, Result<(), PreflightError>);
/// Per-target outcome of an executed reclaim.
pub type ReclaimResult = (TxnPlan, Result<TxnReport, TxnError>);

//! All Darwin-specific and `unsafe` code lives in this module. Everything
//! above it (scanner, index, policy, transactions) stays platform-neutral
//! and depends on the [`ApfsAdapter`] trait, so tests can inject failures
//! at any step without touching a real filesystem.

/// The platform operations a reclamation transaction needs.
pub trait ApfsAdapter: Send + Sync {
    /// APFS copy-on-write clone. `destination` must not exist.
    fn clone_file(&self, source: &Path, destination: &Path) -> io::Result<()>;

    /// Device id of the filesystem holding `path`.
    fn device_of(&self, path: &Path) -> io::Result<u64>;

    /// Whether `path` lives on an APFS filesystem.
    fn is_apfs(&self, path: &Path) -> io::Result<bool>;

    /// Capture a target's restorable metadata.
    fn snapshot_metadata(&self, path: &Path) -> io::Result<MetadataSnapshot>;

    /// Reapply a snapshot to a fresh clone.
    fn restore_metadata(&self, path: &Path, snap: &MetadataSnapshot)
    -> io::Result<RestoreOutcome>;

    /// Full resource-fork contents; empty when absent.
    fn read_resource_fork(&self, path: &Path) -> io::Result<Vec<u8>>;

    /// BSD flags (`st_flags`) of `path`; 0 on platforms without them.
    /// Preflight uses this to reject immutable targets.
    fn bsd_flags(&self, path: &Path) -> io::Result<u32>;
}

/// The real implementation used in production.
pub struct RealApfs;

impl ApfsAdapter for RealApfs {
    fn clone_file(&self, source: &Path, destination: &Path) -> io::Result<()> {
        clone::clone_file(source, destination)
    }
    // …device_of / is_apfs / snapshot_metadata / restore_metadata /
    //   read_resource_fork delegate the same way…

    #[cfg(target_os = "macos")]
    fn bsd_flags(&self, path: &Path) -> io::Result<u32> {
        use std::os::macos::fs::MetadataExt;
        Ok(std::fs::symlink_metadata(path)?.st_flags())
    }

    #[cfg(not(target_os = "macos"))]
    fn bsd_flags(&self, _path: &Path) -> io::Result<u32> {
        Ok(0)
    }
}

#[derive(Clone, Copy, PartialEq)]
enum Fault {
    /// `snapshot_metadata` fails with EIO before anything is mutated.
    Snapshot,
    /// `clonefile` fails with ENOSPC — the disk-full case.
    CloneEnospc,
    /// `restore_metadata` fails with EPERM — the permission case.
    RestorePerm,
    /// Reading the temp clone's resource fork (3rd fork read) fails.
    TempForkRead,
    /// Not a failure: rewrite the target (same size, different bytes)
    /// during `snapshot_metadata` — before the in-txn byte compare.
    MutateEarly,
    /// Rewrite the target during `restore_metadata` — *after* the byte
    /// compare, in the verify-to-swap window.
    MutateLate,
}

fn read_resource_fork(&self, path: &Path) -> io::Result<Vec<u8>> {
    // Executor call order: source (1), target (2), temp (3).
    let call = self.fork_calls.fetch_add(1, Ordering::SeqCst) + 1;
    if self.fault == Fault::TempForkRead && call == 3 {
        return Err(io::Error::from_raw_os_error(libc::EIO));
    }
    self.real.read_resource_fork(path)
}

/// Every failed transaction must leave: the expected target content at the
/// target path (same inode — never swapped), no artifacts, a terminal
/// `rolled-back` journal row, and an untouched source.
fn assert_fully_rolled_back(rig: &Rig, expected_content: &[u8]) {
    assert_eq!(fs::read(&rig.plan.target).unwrap(), expected_content);
    assert_eq!(
        fs::metadata(&rig.plan.target).unwrap().ino(),
        rig.target_ino,
        "target inode must be the original — the swap must not have happened"
    );
    assert!(!rig.plan.temp.exists(), "temp not cleaned up");
    assert!(!rig.plan.backup.exists(), "backup not cleaned up");
    assert_eq!(fs::read(&rig.plan.source).unwrap(), rig.original);

    let entry = rig.db.journal_entry(1).unwrap();
    assert_eq!(entry.state, TxnState::RolledBack);
    assert!(entry.error.is_some(), "rollback must record its cause");
    assert!(rig.db.journal_incomplete().unwrap().is_empty());
}

/// A fully specified reclamation: replace `target` with a clone of
/// `source`, staged at `temp`, keeping `backup` until final validation.
/// Temp and backup live in the target's directory so both renames are
/// same-directory and atomic.
#[derive(Debug, Clone)]
pub struct TxnPlan {
    pub group_id: i64,
    pub source: PathBuf,
    pub target: PathBuf,
    pub temp: PathBuf,
    pub backup: PathBuf,
    pub size: u64,
    pub expected: ExpectedTarget,
}

/// Build the transaction plan for one eligible target of a group.
pub fn make_plan(group: &DuplicateGroup, target: &GroupMember) -> TxnPlan {
    let dir = target.path.parent().unwrap_or(Path::new("."));
    let token = format!("{:016x}", rand::random::<u64>());
    TxnPlan {
        group_id: group.id,
        source: group.source().path.clone(),
        target: target.path.clone(),
        temp: dir.join(format!(".filecleaner.{token}.tmp")),
        backup: dir.join(format!(".filecleaner.{token}.backup")),
        size: group.size,
        expected: ExpectedTarget {
            ino: target.ino,
            size: group.size,
            mtime_sec: target.mtime_sec,
            mtime_nsec: target.mtime_nsec,
        },
    }
}

/// Cheap safety checks, run immediately before a transaction (and for dry
/// runs). Reads only — never mutates the filesystem. Content identity is
/// deliberately NOT checked here; the executor byte-compares both forks
/// inside the journaled transaction.
pub fn preflight(plan: &TxnPlan, adapter: &dyn ApfsAdapter) -> Result<(), PreflightError> {
    use std::os::unix::fs::MetadataExt;

    let target_meta = std::fs::symlink_metadata(&plan.target).map_err(|err| {
        if err.kind() == std::io::ErrorKind::NotFound {
            PreflightError::TargetChanged
        } else {
            PreflightError::Io(err)
        }
    })?;
    if !target_meta.is_file() {
        return Err(PreflightError::TargetNotRegular);
    }
    if target_meta.ino() != plan.expected.ino
        || target_meta.len() != plan.expected.size
        || target_meta.mtime() != plan.expected.mtime_sec
        || target_meta.mtime_nsec() != plan.expected.mtime_nsec
    {
        return Err(PreflightError::TargetChanged);
    }
    if target_meta.nlink() > 1 {
        return Err(PreflightError::TargetHardlinked);
    }

    if adapter.device_of(&plan.source)? != adapter.device_of(&plan.target)? {
        return Err(PreflightError::DifferentVolume);
    }
    if !adapter.is_apfs(&plan.target)? {
        return Err(PreflightError::NotApfs);
    }

    let flags = adapter.bsd_flags(&plan.target)?;
    if flags & (UF_IMMUTABLE | SF_IMMUTABLE) != 0 {
        return Err(PreflightError::TargetImmutable);
    }

    std::fs::File::open(&plan.source)
        .map_err(|err| PreflightError::SourceUnreadable(err.to_string()))?;

    let dir = plan.target.parent().unwrap_or(Path::new("."));
    if !dir_writable(dir) {
        return Err(PreflightError::DirNotWritable);
    }

    Ok(())
}

/// `access(2)` check: can this process create and rename entries in `dir`?
/// Read-only, so it is safe during dry runs.
fn dir_writable(dir: &Path) -> bool {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt;

    let Ok(c_dir) = CString::new(dir.as_os_str().as_bytes()) else {
        return false;
    };
    unsafe { libc::access(c_dir.as_ptr(), libc::W_OK | libc::X_OK) == 0 }
}

/// Plan every eligible target of a group and run read-only preflight on
/// each. Mutates nothing — this is the `--dry-run` path.
pub fn dry_run_group(
    db_path: &Path,
    group_id: i64,
) -> Result<(DuplicateGroup, Vec<DryRunResult>)> {
    let group = get_group(db_path, group_id)?;
    let adapter = RealApfs;
    let results = group
        .eligible_targets()
        .map(|target| {
            let plan = planner::make_plan(&group, target);
            let verdict = planner::preflight(&plan, &adapter);
            (plan, verdict)
        })
        .collect();
    Ok((group, results))
}

/// How far the filesystem was mutated, for rollback.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Progress {
    Clean,
    TempCreated,
    BackupRenamed,
    TargetSwapped,
}

// 2. Identity: the byte comparison is the final authority, run inside
//    the transaction so nothing can change between check and swap
//    without being caught by the rename of that exact inode.
let identical = data_forks_identical(&plan.source, &plan.target)
    .map_err(|e| fail(progress, e.into()))?;
if !identical {
    return Err(fail(
        progress,
        TxnError::Identity("source and target data forks differ".into()),
    ));
}
let source_fork = adapter
    .read_resource_fork(&plan.source)
    .map_err(|e| fail(progress, e.into()))?;
let target_fork = adapter
    .read_resource_fork(&plan.target)
    .map_err(|e| fail(progress, e.into()))?;
if source_fork != target_fork {
    return Err(fail(
        progress,
        TxnError::Identity("source and target resource forks differ".into()),
    ));
}

// 6. Swap, journaling each rename before it happens.
db.journal_set_state(journal_id, TxnState::BackupCreated, None)
    .map_err(|e| fail(progress, TxnError::Db(e.to_string())))?;
fs::rename(&plan.target, &plan.backup).map_err(|e| fail(progress, e.into()))?;
progress = Progress::BackupRenamed;

// Close the verify-to-swap race: rename preserves the inode, so the
// renamed backup must still match what the scan recorded. A target
// mutated at any point since preflight shows up here (mtime/size) and
// rolls back — the user's edit wins, not the clone.
let backup_meta = fs::symlink_metadata(&plan.backup).map_err(|e| fail(progress, e.into()))?;
if backup_meta.ino() != plan.expected.ino
    || backup_meta.len() != plan.expected.size
    || backup_meta.mtime() != plan.expected.mtime_sec
    || backup_meta.mtime_nsec() != plan.expected.mtime_nsec
{
    return Err(fail(
        progress,
        TxnError::Identity("target changed during the transaction".into()),
    ));
}

db.journal_set_state(journal_id, TxnState::Swapped, None)
    .map_err(|e| fail(progress, TxnError::Db(e.to_string())))?;
fs::rename(&plan.temp, &plan.target).map_err(|e| fail(progress, e.into()))?;
progress = Progress::TargetSwapped;

/// Undo according to how far the transaction got. The target ends up back
/// in place in every case.
fn rollback(plan: &TxnPlan, progress: Progress) -> io::Result<()> {
    match progress {
        Progress::Clean => Ok(()),
        Progress::TempCreated => remove_if_exists(&plan.temp),
        Progress::BackupRenamed => {
            remove_if_exists(&plan.temp)?;
            if !plan.target.exists() && plan.backup.exists() {
                fs::rename(&plan.backup, &plan.target)?;
            }
            Ok(())
        }
        Progress::TargetSwapped => {
            // The clone sits at the target path but failed validation:
            // discard it and restore the original from backup.
            if plan.backup.exists() {
                remove_if_exists(&plan.target)?;
                fs::rename(&plan.backup, &plan.target)?;
            }
            remove_if_exists(&plan.temp)
        }
    }
}

Err((progress, err)) => {
    let message = match rollback(plan, progress) {
        Ok(()) => err.to_string(),
        Err(rb_err) => format!("{err}; ROLLBACK INCOMPLETE: {rb_err}"),
    };
    let _ = db.journal_set_state(journal_id, TxnState::RolledBack, Some(&message));
    Err(err)
}

/// Streaming byte-for-byte comparison of two data forks.
pub fn data_forks_identical(a: &Path, b: &Path) -> io::Result<bool> {
    let mut fa = fs::File::open(a)?;
    let mut fb = fs::File::open(b)?;
    if fa.metadata()?.len() != fb.metadata()?.len() {
        return Ok(false);
    }
    let mut buf_a = vec![0u8; 1024 * 1024];
    let mut buf_b = vec![0u8; 1024 * 1024];
    loop {
        let n = read_full(&mut fa, &mut buf_a)?;
        let m = read_full(&mut fb, &mut buf_b)?;
        if n != m || buf_a[..n] != buf_b[..m] {
            return Ok(false);
        }
        if n == 0 {
            return Ok(true);
        }
    }
}

Ok(mut warnings) => {
    // Past this point the swap is validated: never roll back.
    if let Err(err) = fs::remove_file(&plan.backup) {
        warnings.push(format!(
            "backup not removed ({}): {err}; recovery will clean it up",
            plan.backup.display()
        ));
    }
    if let Err(err) = db.journal_set_state(journal_id, TxnState::Committed, None) {
        warnings.push(format!(
            "journal not marked committed: {err}; recovery will complete it"
        ));
    }

/// Everything we capture from a target before replacing it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MetadataSnapshot {
    /// Permission bits including setuid/setgid/sticky (`st_mode & 0o7777`).
    pub mode: u32,
    pub uid: u32,
    pub gid: u32,
    /// BSD flags (`st_flags`): UF_HIDDEN, UF_IMMUTABLE, …
    pub flags: u32,
    pub atime: (i64, i64),
    pub mtime: (i64, i64),
    /// Birth time; restored via `setattrlist` where possible.
    pub crtime: Option<(i64, i64)>,
    /// All extended attributes, sorted by name. Includes
    /// `com.apple.FinderInfo` and `com.apple.ResourceFork`.
    pub xattrs: Vec<(String, Vec<u8>)>,
    /// ACL in text form, `None` when the file has no ACL.
    pub acl_text: Option<String>,
}

/// What a restore actually accomplished. Ownership and ACL restoration can
/// legitimately fail without privileges; the caller decides whether partial
/// fidelity is acceptable before committing the swap.
#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct RestoreOutcome {
    pub ownership_restored: bool,
    pub crtime_restored: bool,
    pub warnings: Vec<String>,
}

/// Reapply a snapshot to `path` (the fresh clone). Hard failures on
/// mode/xattrs/times return `Err`; ownership, ACL, and birth-time
/// restoration degrade to warnings because they can require privileges
/// the process legitimately lacks.
///
/// Order matters: xattrs and ACL first, then ownership (chown clears
/// setuid bits), then mode, then times (earlier steps touch them), and
/// BSD flags last — an immutable flag would block every other step.
pub fn restore(path: &Path, snap: &MetadataSnapshot) -> io::Result<RestoreOutcome> {
    let mut outcome = RestoreOutcome::default();

    // Xattrs: remove strays inherited from the source, then write the
    // target's set.
    let wanted: std::collections::HashSet<&str> =
        snap.xattrs.iter().map(|(n, _)| n.as_str()).collect();
    for existing in list_xattrs(path)? {
        if !wanted.contains(existing.as_str()) {
            remove_xattr(path, &existing)?;
        }
    }
    for (name, value) in &snap.xattrs {
        set_xattr(path, name, value)?;
    }

pub(super) fn list_xattrs(path: &Path) -> io::Result<Vec<String>> {
    let c_path = cpath(path)?;
    loop {
        let size = unsafe {
            libc::listxattr(
                c_path.as_ptr(),
                std::ptr::null_mut(),
                0,
                libc::XATTR_NOFOLLOW,
            )
        };
        if size < 0 {
            return Err(io::Error::last_os_error());
        }
        if size == 0 {
            return Ok(Vec::new());
        }
        let mut buf = vec![0u8; size as usize];
        let read = unsafe {
            libc::listxattr(
                c_path.as_ptr(),
                buf.as_mut_ptr().cast(),
                buf.len(),
                libc::XATTR_NOFOLLOW,
            )
        };
        if read < 0 {
            let err = io::Error::last_os_error();
            // The list grew between the two calls; retry.
            if err.raw_os_error() == Some(libc::ERANGE) {
                continue;
            }
            return Err(err);
        }
        buf.truncate(read as usize);
        return Ok(buf
            .split(|&b| b == 0)
            .filter(|name| !name.is_empty())
            .map(|name| String::from_utf8_lossy(name).into_owned())
            .collect());
    }
}

// The libc crate does not bind Darwin's ACL API; declare what we use.
type AclT = *mut libc::c_void;
const ACL_TYPE_EXTENDED: libc::c_uint = 0x100;

unsafe extern "C" {
    fn acl_get_link_np(path: *const libc::c_char, acl_type: libc::c_uint) -> AclT;
    fn acl_set_link_np(
        path: *const libc::c_char,
        acl_type: libc::c_uint,
        acl: AclT,
    ) -> libc::c_int;
    fn acl_to_text(acl: AclT, len_p: *mut libc::ssize_t) -> *mut libc::c_char;
    fn acl_from_text(text: *const libc::c_char) -> AclT;
    fn acl_init(count: libc::c_int) -> AclT;
    fn acl_free(obj: *mut libc::c_void) -> libc::c_int;
}

// No ACL on the target: install an empty one so nothing
// inherited from the source survives.
None => {
    let acl = unsafe { acl_init(0) };
    if acl.is_null() {
        return Err(io::Error::last_os_error());
    }
    acl
}

/// Full resource-fork contents; empty when the file has none.
#[cfg(target_os = "macos")]
pub fn read_resource_fork(path: &Path) -> io::Result<Vec<u8>> {
    match crate::apfs::metadata::darwin_get_xattr(path, RESOURCE_FORK_XATTR) {
        Ok(data) => Ok(data),
        Err(err) if err.raw_os_error() == Some(libc::ENOATTR) => Ok(Vec::new()),
        Err(err) => Err(err),
    }
}

/// Transaction states, journaled durably *before* the filesystem step each
/// one precedes. After a crash, the journal plus what is actually on disk
/// determines recovery:
///
/// - `Prepared`     → nothing user-visible has changed; roll back.
/// - `BackupCreated`→ target may have been renamed to the backup; roll back.
/// - `Swapped`      → the clone was fully verified; roll forward.
/// - terminal states record the outcome.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TxnState {
    /// Intent recorded; covers temp-clone creation and verification.
    Prepared,
    /// Written before `rename(target, backup)`.
    BackupCreated,
    /// Written before `rename(temp, target)`.
    Swapped,
    /// Final validation passed and the backup was removed.
    Committed,
    /// The transaction was undone; the target is untouched.
    RolledBack,
}

/// Legal state-machine transitions. Forward progress is strictly
/// ordered; any non-terminal state may roll back; `Swapped` may commit
/// directly (recovery rolls forward from there).
pub fn can_transition(self, next: TxnState) -> bool {
    use TxnState::*;
    matches!(
        (self, next),
        (Prepared, BackupCreated)
            | (BackupCreated, Swapped)
            | (Swapped, Committed)
            | (Prepared, RolledBack)
            | (BackupCreated, RolledBack)
            | (Swapped, RolledBack)
    )
}

if !current.can_transition(next) {
    anyhow::bail!(
        "illegal journal transition for row {id}: {} -> {}",
        current.as_str(),
        next.as_str()
    );
}

TxnState::Swapped => {
    // The temp clone passed full verification before `swapped` was
    // journaled, so completing the swap is the safe direction.
    if !entry.target.exists() && entry.temp.exists() {
        fs::rename(&entry.temp, &entry.target)?;
        if let Some(dir) = entry.target.parent() {
            let _ = fsync_dir(dir);
        }
    }
    if entry.target.exists() {
        remove_if_exists(&entry.backup)?;
        db.journal_set_state(entry.id, TxnState::Committed, None)?;
        Ok("rolled forward (swap completed, backup removed)".into())
    } else if entry.backup.exists() {
        // Clone lost mid-crash; fall back to the original.
        fs::rename(&entry.backup, &entry.target)?;
        remove_if_exists(&entry.temp)?;
        db.journal_set_state(
            entry.id,
            TxnState::RolledBack,
            Some("clone lost during interruption; target restored from backup"),
        )?;
        Ok("rolled back (clone was lost; target restored from backup)".into())
    } else {
        db.journal_set_state(
            entry.id,
            TxnState::RolledBack,
            Some("neither target, temp, nor backup found; manual attention required"),
        )?;
        Ok("UNRESOLVED: neither target, temp, nor backup exists".into())
    }
}

/// Repair every interrupted transaction found in the journal. Returns a
/// human-readable description of each repair. Safe to run on every launch;
/// an empty journal is a no-op.
pub fn recover_all(db: &mut Db) -> Result<Vec<String>> {
    let mut actions = Vec::new();
    for entry in db.journal_incomplete()? {
        let action = recover_one(db, &entry)?;
        actions.push(format!(
            "txn #{} ({}): {}",
            entry.id,
            entry.target.display(),
            action
        ));
    }
    Ok(actions)
}

/// Repair any transactions interrupted by a crash or kill. Run on every
/// launch; returns a description of each repair performed.
pub fn recover(db_path: &Path) -> Result<Vec<String>> {
    if !db_path.exists() {
        return Ok(Vec::new());
    }
    let mut db = Db::open(db_path)?;
    recovery::recover_all(&mut db)
}

